package dev.mcpmcp.core;
import java.nio.file.*;import java.util.*;
/** Text-only capability limited to the plugin tree; rejects traversal, aliases and binary installation. */
public final class PluginFiles {
 private final Path root;public PluginFiles(Path r){root=r.toAbsolutePath().normalize();try{Files.createDirectories(root);if(Files.isSymbolicLink(root))throw new IllegalArgumentException("plugin_root_symlink");}catch(java.io.IOException e){throw new IllegalArgumentException("plugin_root_unavailable",e);}}
 public Path resolve(String relative){if(relative==null||relative.isBlank()||relative.length()>512||relative.contains("\\")||relative.contains(":")||relative.startsWith("/")||relative.indexOf(0)>=0)throw new IllegalArgumentException("invalid_plugin_path");Path p=root.resolve(relative).normalize();if(!p.startsWith(root)||p.equals(root))throw new IllegalArgumentException("plugin_path_escape");for(Path q=p;q!=null&&q.startsWith(root);q=q.getParent()){if(Files.isSymbolicLink(q))throw new IllegalArgumentException("plugin_symlink_denied");if(Files.exists(q,LinkOption.NOFOLLOW_LINKS))try{if(!q.toRealPath().startsWith(root.toRealPath()))throw new IllegalArgumentException("plugin_realpath_escape");}catch(java.io.IOException e){throw new IllegalArgumentException("plugin_path_unavailable",e);}}return p;}
 private Path textPath(String s){Path p=resolve(s);String n=p.getFileName().toString().toLowerCase(Locale.ROOT);if(!n.endsWith(".json")&&!n.endsWith(".md")&&!n.endsWith(".txt"))throw new IllegalArgumentException("plugin_text_only");return p;}
 public String read(String path){try{Path p=textPath(path);if(Files.size(p)>262144)throw new IllegalArgumentException("plugin_file_too_large");return Files.readString(p);}catch(java.io.IOException e){throw new IllegalArgumentException("plugin_file_unavailable",e);}}
 public void write(String path,String text){try{if(text.length()>262144||text.getBytes(java.nio.charset.StandardCharsets.UTF_8).length>262144)throw new IllegalArgumentException("plugin_file_too_large");Path p=textPath(path);Files.createDirectories(p.getParent());Path temp=Files.createTempFile(p.getParent(),".mcpmcp-",".tmp");try{Files.writeString(temp,text);resolve(path);Files.move(temp,p,StandardCopyOption.REPLACE_EXISTING,StandardCopyOption.ATOMIC_MOVE);}finally{Files.deleteIfExists(temp);}}catch(java.io.IOException e){throw new IllegalArgumentException("plugin_write_failed",e);}}
}
